import {Ago} from '@github-ui/ago'
import {ActionList, ActionMenu, Button, Heading, IconButton, Label, Link} from '@primer/react'
import {KebabHorizontalIcon} from '@primer/octicons-react'
import {type Alert, AlertStatus} from '../../types/alert-types'
import {AlertDismissal as AlertDismissalShared} from '../shared/AlertDismissal'
import type {PatternInfo} from '../../types/pattern-info-types'
import {UserFeedbackBanner} from '../shared/UserFeedbackBanner'
import {secretScanningCustomPatternPath, secretScanningIndexPath} from '../../paths'
import type {Repository} from '../../types/repo-types'
import {AlertClosureRequest} from '../shared/AlertClosureRequest'
import {useContext} from 'react'
import {TimelineContext} from '../shared/TimelineContext'
import {CopilotSurvey, type CopilotSurveyProps} from '@github-ui/copilot-survey/CopilotSurvey'

export function ShowHeader({
  alert,
  repository,
  patternInfo,
  commitAuthorMode,
  showUserFeedbackLink,
  userFeedbackNotice,
  resolveAlertsAllowed,
  delegatedClosuresEnabled,
  existingClosureRequestNumber,
  existingClosureRequestPending,
  userCanReviewClosureRequests,
  showGenericSecretsFeedbackNotice,
  genericSecretsFeedbackNotice,
  selfServeBanner,
}: {
  alert: Alert
  repository: Repository
  patternInfo: PatternInfo
  commitAuthorMode: boolean
  showUserFeedbackLink: boolean
  userFeedbackNotice: string
  resolveAlertsAllowed: boolean
  delegatedClosuresEnabled: boolean
  existingClosureRequestNumber: number
  existingClosureRequestPending: boolean
  userCanReviewClosureRequests: boolean
  showGenericSecretsFeedbackNotice: boolean
  genericSecretsFeedbackNotice: string
  selfServeBanner?: CopilotSurveyProps
}) {
  const alertStatus: AlertStatus = alert.is_closed ? AlertStatus.CLOSED : AlertStatus.OPEN

  return (
    <>
      {selfServeBanner && (
        <div className="mb-3" data-testid="self-serve-banner">
          <CopilotSurvey {...selfServeBanner} />
        </div>
      )}
      <UserFeedbackBanner showBannerOnLoad={showUserFeedbackLink} notice={userFeedbackNotice}>
        <span className="mr-1">We want to better understand our users&apos; needs and experiences.</span>
        <Link href="https://forms.gle/Uhjq5VbLT5D3ELTL9" className="mr-1">
          Book some time with us
        </Link>
        <span>to discuss the GitHub secret scanning experience.</span>
      </UserFeedbackBanner>
      <UserFeedbackBanner showBannerOnLoad={showGenericSecretsFeedbackNotice} notice={genericSecretsFeedbackNotice}>
        <span className="mr-1">Share your feedback on generic password detection with</span>
        <Link href="https://gh.io/password-survey" className="mr-0">
          this survey
        </Link>
        <span>. It will take you less than two minutes.</span>
      </UserFeedbackBanner>
      {commitAuthorMode ? (
        <span className="mr-1">Secret scanning alerts</span>
      ) : (
        <Link href={secretScanningIndexPath(repository.owner_display_login, repository.name)} className="mr-1">
          Secret scanning alerts
        </Link>
        // eslint-disable-next-line react-google-translate/no-conditional-text-nodes-with-siblings
      )}
      / #{alert.number}
      <div className="d-flex">
        <Heading as="h1" className="text-normal mt-2">
          {alert.label}
        </Heading>
        <div className="d-flex flex-items-center ml-auto">
          {patternInfo.render_link && <CustomPatternOptions patternInfo={patternInfo} repository={repository} />}
          {resolveAlertsAllowed && (
            <AlertDismissalOrClosureRequest
              repository={repository}
              alertStatus={alertStatus}
              alignEnd
              alert={alert}
              delegatedClosuresEnabled={delegatedClosuresEnabled}
              existingClosureRequestNumber={existingClosureRequestNumber}
              existingClosureRequestPending={existingClosureRequestPending}
              userCanReviewClosureRequests={userCanReviewClosureRequests}
            />
          )}
        </div>
      </div>
      <div className="d-flex">
        <Label variant="secondary">{alertStatus.toString()}</Label>
        <div className="d-flex flex-items-center ml-2 fgColor-muted">
          <span className="text-bold">GitHub</span>
          <span className="ml-1">detected a</span>
          <PatternType patternInfo={patternInfo} repository={repository} />
          <Ago timestamp={new Date(alert.created_at)} />
        </div>
      </div>
    </>
  )
}

function AlertDismissalOrClosureRequest({
  repository,
  alertStatus,
  alignEnd,
  alert,
  delegatedClosuresEnabled,
  existingClosureRequestNumber,
  existingClosureRequestPending,
  userCanReviewClosureRequests,
}: {
  repository: Repository
  alertStatus: AlertStatus
  alignEnd: boolean
  alert: Alert
  delegatedClosuresEnabled: boolean
  existingClosureRequestNumber: number
  existingClosureRequestPending: boolean
  userCanReviewClosureRequests: boolean
}) {
  const {signalTimelineRefetch} = useContext(TimelineContext)

  // If delegated alert dismissal is not enabled, return the usual alert dismissal component.
  if (!delegatedClosuresEnabled) {
    return (
      <AlertDismissalShared
        repository={repository}
        alertStatus={alertStatus}
        alertNumbers={[alert.number]}
        redirectUrl={`/${repository.owner_display_login}/${repository.name}/security/secret-scanning/${alert.number}`}
        alignEnd={alignEnd}
        alerts={[alert]}
      />
    )
  }

  // If there is an existing closure request, it will be linked in the timeline.
  if (existingClosureRequestNumber !== 0) {
    if (existingClosureRequestPending) {
      // But display an inactive button here instead, if the request is pending
      return <Button disabled>Request pending</Button>
    } else if (alert.is_closed) {
      // If it's not pending and the alert is closed, display the reopen button
      return (
        <AlertDismissalShared
          repository={repository}
          alertStatus={alertStatus}
          alertNumbers={[alert.number]}
          redirectUrl={`/${repository.owner_display_login}/${repository.name}/security/secret-scanning/${alert.number}`}
          alignEnd={alignEnd}
          alerts={[alert]}
        />
      )
    }
    // If the alert is open, fall back to AlertClosureRequest
  }

  // Reviewers can close alerts themselves, as usual.
  if (userCanReviewClosureRequests) {
    return (
      <AlertDismissalShared
        repository={repository}
        alertStatus={alertStatus}
        alertNumbers={[alert.number]}
        redirectUrl={`/${repository.owner_display_login}/${repository.name}/security/secret-scanning/${alert.number}`}
        alignEnd={alignEnd}
        alerts={[alert]}
      />
    )
  }

  return (
    <AlertClosureRequest
      repository={repository}
      alertNumber={alert.number}
      redirectUrl={`/${repository.owner_display_login}/${repository.name}/security/secret-scanning/${alert.number}`}
      onDismiss={signalTimelineRefetch}
      shouldShowDismissButton={alertStatus === AlertStatus.OPEN}
    />
  )
}

function PatternType({patternInfo, repository}: {patternInfo: PatternInfo; repository: Repository}) {
  const patternTypeString: string = patternInfo.is_custom ? 'custom pattern' : 'secret'

  if (patternInfo.render_link) {
    const patternUrl = customPatternPath(patternInfo, repository)
    return (
      <Link href={patternUrl} className="ml-1 mr-1">
        {patternTypeString}
      </Link>
    )
  }
  return <span className="ml-1 mr-1">{patternTypeString}</span>
}

function CustomPatternOptions({patternInfo, repository}: {patternInfo: PatternInfo; repository: Repository}) {
  if (patternInfo.is_custom) {
    return (
      <div className="mr-2" data-testid={'custom-pattern-alert-options'}>
        <ActionMenu>
          <ActionMenu.Anchor>
            <IconButton icon={KebabHorizontalIcon} aria-label="Show custom pattern options" />
          </ActionMenu.Anchor>

          <ActionMenu.Overlay>
            <ActionList>
              <ActionList.Item>
                <Link href={customPatternPath(patternInfo, repository)} muted>
                  Edit custom pattern
                </Link>
              </ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>
    )
  }

  return null
}

function customPatternPath(patternInfo: PatternInfo, repository: Repository) {
  return secretScanningCustomPatternPath(
    patternInfo.id,
    repository.owner_display_login,
    patternInfo.scope === 'REPOSITORY_SCOPE' ? repository.name : null,
  )
}

try{ ShowHeader.displayName ||= 'ShowHeader' } catch {}
try{ AlertDismissalOrClosureRequest.displayName ||= 'AlertDismissalOrClosureRequest' } catch {}
try{ PatternType.displayName ||= 'PatternType' } catch {}
try{ CustomPatternOptions.displayName ||= 'CustomPatternOptions' } catch {}