import type {DisplayedUser} from './user-types'

export interface TokenCampaignMetadata {
  name: string
  completion_percentage?: number
  ends_at: string
  number: number
}

export interface TokenMetadata {
  access_id: number
  token_type: string
  name?: string
  owner?: DisplayedUser
  link?: string
  created_at: string
  expires_at?: string
  last_accessed_at?: string
  is_owner_suspended: boolean
  campaigns?: TokenCampaignMetadata
}

export const TokenAccess = {
  OrgAccess: 'ORG_ACCESS',
  SSOAccess: 'SSO_ACCESS',
  NoAccess: 'NO_ACCESS',
  PublicAccess: 'PUBLIC_ACCESS',
} as const

export type TokenAccess = (typeof TokenAccess)[keyof typeof TokenAccess]
