import {
  type FilterKey,
  type FilterProviderOptions,
  type FilterSuggestion,
  NOT_SHOWN,
  ProviderSupportStatus,
  type SuppliedFilterProviderOptions,
} from '@github-ui/filter'
import {
  AlertIcon,
  AppsIcon,
  ArrowSwitchIcon,
  CheckCircleIcon,
  GoalIcon,
  KeyIcon,
  MentionIcon,
  OrganizationIcon,
  PersonIcon,
  SortDescIcon,
} from '@primer/octicons-react'
import {SelectFilterProvider} from '@github-ui/filter/providers'
import {FetchedFilterProvider} from './fetched-filter-provider'

export class ClosureReasonFilterProvider extends SelectFilterProvider {
  constructor(closureReasons: FilterSuggestion[], options?: SuppliedFilterProviderOptions) {
    super(FILTER_KEYS.closureReason, closureReasons, options)
  }
}

export class BypassedFilterProvider extends SelectFilterProvider {
  constructor(bypassedOptions: FilterSuggestion[]) {
    super(FILTER_KEYS.bypassed, bypassedOptions, {
      // exclusive is- you cannot do -bypassed:false|true.
      // multivalue is false- you cannot do bypassed:true,false. The bypass filter can be removed to show all results.
      filterTypes: {valueless: false, hasValue: false, exclusive: false, multiValue: false},
    })
  }
}
export class ValidityFilterProvider extends SelectFilterProvider {
  constructor(validityOptions: FilterSuggestion[], options?: SuppliedFilterProviderOptions) {
    super(FILTER_KEYS.validity, validityOptions, options)
  }
}

export class AssigneeFilterProvider extends SelectFilterProvider {
  constructor(assigneeOptions: FilterSuggestion[]) {
    super(FILTER_KEYS.assignee, assigneeOptions, {strictMatching: false})
  }
}

export class SecretTypeFilterProvider extends FetchedFilterProvider {
  constructor(
    getSecretTypes: () => Promise<FilterSuggestion[]>,
    getAllValidSecretTypes: () => Promise<FilterSuggestion[]>,
    options?: SuppliedFilterProviderOptions,
  ) {
    super(FILTER_KEYS.secretType, getSecretTypes, getAllValidSecretTypes, options)
  }
}

export class ProviderFilterProvider extends FetchedFilterProvider {
  constructor(
    getProviders: () => Promise<FilterSuggestion[]>,
    getAllValidProviders: () => Promise<FilterSuggestion[]>,
    options?: SuppliedFilterProviderOptions,
  ) {
    super(FILTER_KEYS.provider, getProviders, getAllValidProviders, options)
  }
}

export class IsFilterProvider extends SelectFilterProvider {
  constructor(includePlaidFilters?: boolean, options?: SuppliedFilterProviderOptions) {
    let values = FILTER_VALUES.is
    if (!includePlaidFilters) {
      values = values.filter(value => value.value !== 'multi-repository' && value.value !== 'publicly-leaked')
    }
    super(FILTER_KEYS.is, values, options)
  }
}

export class SortFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    super(FILTER_KEYS.sort, FILTER_VALUES.sort, options)
  }
}

export class ResultsCategoryFilterProvider extends SelectFilterProvider {
  constructor() {
    super(FILTER_KEYS.results, FILTER_VALUES.results, resultsCategoryFilterProviderOptions)
  }
}

export class CampaignFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    const campaignOptions = {
      ...options,
      filterTypes: {inclusive: true, exclusive: false, valueless: false, hasValue: false},
    }
    super(FILTER_KEYS.campaign, FILTER_VALUES.campaign, campaignOptions)
  }
}

