import {clsx} from 'clsx'
import {Label, Link, Truncate} from '@primer/react'
import {useQuery} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {
  TokenVerificationStatus,
  verificationStatusToText,
  type Alert,
  type OnDemandValidation,
} from '../../../types/alert-types'
import type {Repository} from '../../../types/repo-types'
import {secretScanningPartnerTokenMetadataPath, securityAnalysisSettingsPath} from '../../../paths'
import {TokenMetadataSection} from './TokenMetadataSection'
import {ViewTableRow, ViewTable} from './TokenMetadataTable'
import {MetadataKeys, type MetadataKey, keysWithBoldValue} from './MetadataKeys'

interface Metadata {
  raw: string
  metadata: Parts[]
}

interface Parts {
  key: string
  value: string
}

function formatMetadata(key: MetadataKey, value: string): string {
  if (key !== MetadataKeys.SecretIssuedDate && key !== MetadataKeys.SecretExpiryDate) {
    return value
  }

  const date = new Date(value)
  if (isNaN(date.getTime())) {
    return value
  }

  return date.toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

export function PartnerTokenMetadataPane({
  enabled,
  canManageRepoSecurity,
  alert,
  repo,
}: {
  enabled: boolean
  canManageRepoSecurity: boolean
  alert: Alert
  repo: Repository
}) {
  // this query is just to get any updated validity (an OnDemandValidation) that was performed
  // by an on-demand check. this query is not enabled and the queryFn should never be called- there
  // is no reason to update the value of this data (with a new OnDemandValidation result) from this
  // component (it would only be updated as a result of an on-demand check, which is from the refresh
  // validity button). that component uses a `useMutation` to perform the on-demand check and updates
  // the query key below with the result. here, we just query the cache with the queryKey.
  const {data: validityData} = useQuery<OnDemandValidation>({
    enabled: false,
    queryKey: ['secret-scanning', 'validation-result', alert.number],
    queryFn: async (): Promise<OnDemandValidation> => {
      throw new Error('it should never be called from here!')
    },
  })

  const {data, isLoading, isError} = useQuery({
    enabled: enabled && tokenIsOrBecameActive(alert, validityData),
    queryKey: ['secret-scanning-metadata', alert.number, repo.owner_display_login, repo.name],
    queryFn: async (): Promise<Metadata> => {
      const mdResponse = await reactFetchJSON(
        secretScanningPartnerTokenMetadataPath(repo.owner_display_login, repo.name, alert.number),
        {method: 'GET'},
      )
      if (!mdResponse.ok) {
        throw new Error('fetch failed')
      }
      const metadata = await mdResponse.json()
      return metadata.metadata
    },
  })

  if (!tokenIsOrBecameActive(alert, validityData)) {
    return null
  }

  if (isLoading) {
    return null
  }

  if (isError) {
    return <span className="fgColor-danger f6">Error loading metadata</span>
  }

  if (enabled && !data) {
    return null
  }

  let tableRows = null
  const validityRow = (
    <MetadataPart
      data-testid="metadata-validity"
      part={{key: MetadataKeys.Validity, value: verificationStatusToText(getValidity(alert, validityData))}}
    />
  )
  if (!enabled) {
    tableRows = (
      <>
        {validityRow}
        {canManageRepoSecurity && (
          // 32px height to get it to match height of rows with copy buttons
          <ViewTableRow style={{height: '32px'}} keyCell={MetadataKeys.Other}>
            <Link
              inline
              href={securityAnalysisSettingsPath(repo.owner_display_login, repo.name)}
              data-testid="enable-metadata-cta"
            >
              Enable in settings
            </Link>
          </ViewTableRow>
        )}
      </>
    )
  } else if (data) {
    tableRows = (
      <>
        {validityRow}
        {data.metadata.map(part => {
          return part.value.split('\n').map((value, index) => {
            return <MetadataPart key={`${part.key} ${value}`} index={index} part={{key: part.key, value}} />
          })
        })}
      </>
    )
  }

  return (
    <TokenMetadataSection className="width-full">
      <ViewTable
        header={
          <>
            <span className="f6 fgColor-muted text-bold">{alert.label}</span>
            <Label className="ml-2" variant="success">
              Preview
            </Label>
          </>
        }
        className="d-flex flex-column gap-1"
      >
        {tableRows}
      </ViewTable>
    </TokenMetadataSection>
  )
}

// Wrapper around ViewTableRow to handle bolding, copy button, etc.
function MetadataPart({
  index = 0,
  part: {key, value},
  ...props
}: {
  index?: number
  part: Parts
  'data-testid'?: string
}) {
  const formattedValue = formatMetadata(key, value)
  return (
    <ViewTableRow keyCell={index === 0 && key} data-testid={props['data-testid']}>
      {/* Need d-block to get truncation to work */}
      <Truncate title={formattedValue} className={clsx('d-block', keysWithBoldValue.includes(key) && 'text-superbold')}>
        {formattedValue}
      </Truncate>
      <CopyToClipboardButton
        // v-hidden used to hide button so that it still takes up space and keeps row height consistent
        className={clsx('ml-auto', key === MetadataKeys.Validity && 'v-hidden')}
        textToCopy={formattedValue}
        data-testid="metadata-copy-btn"
      />
    </ViewTableRow>
  )
}

function getValidity(alert: Alert, validityData?: OnDemandValidation) {
  // try to get the updated validity (from an on-demand check) first, if it's there
  if (validityData?.validity) {
    return validityData.validity
  }
  // no on-demand check performed, just get the validity from the alert payload
  return alert.validity
}

function tokenIsOrBecameActive(alert: Alert, validityData?: OnDemandValidation) {
  const validity = getValidity(alert, validityData)
  return validity === TokenVerificationStatus.TOKEN_VALIDITY_ACTIVE
}

try{ PartnerTokenMetadataPane.displayName ||= 'PartnerTokenMetadataPane' } catch {}
try{ MetadataPart.displayName ||= 'MetadataPart' } catch {}