import {clsx} from 'clsx'
import styles from './TokenMetadataSection.module.css'

export function TokenMetadataSection({
  className,
  children,
  sectionName,
}: {
  className?: string
  children: React.ReactNode
  sectionName?: string
}) {
  return (
    <div className={clsx(styles.section, 'd-flex flex-column pb-3', className)}>
      {sectionName && <span className={styles.Text}>{sectionName}</span>}
      {children}
    </div>
  )
}

try{ TokenMetadataSection.displayName ||= 'TokenMetadataSection' } catch {}